#
# Structure for table "docs"
#

CREATE TABLE `docs` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `doc_id_procedure` varchar(20) DEFAULT NULL,
  `doc_pessoa` int(11) DEFAULT NULL,
  `doc_tipo` varchar(150) DEFAULT NULL,
  `doc_documento` varchar(150) DEFAULT NULL,
  `doc_conteudo` longtext,
  `doc_obs` varchar(255) DEFAULT NULL,
  `doc_status` int(11) DEFAULT '1',
  `doc_post` varchar(20) DEFAULT NULL,
  `doc_time` varchar(10) DEFAULT NULL,
  `doc_update` varchar(20) DEFAULT NULL,
  `doc_user` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=397 DEFAULT CHARSET=utf8mb4;

