INSERT INTO `docs` VALUES (8,'0011',NULL,'1','1','\n        <br>\n        <br>\n        \n    <div class=\"col-12\" style=text-align:center>\n      <img src=\"https://e-reurbsistema.com.br/sistema/assets/icones/325-Reurb-E.png\" class=\"\" width=\"200\"/><br>\n    </div>\n    \n         <br><br>\n         <h1 style=text-align:center>DESPACHO</h1>\n         <br>\n\n         <div class=\"conteudo\">\n\n            \n            Procedimento nº: <b>0011</b><br>\n            Nome do núcleo urbano regularizado: <b>BAIRRO GOMES </b><br>\n            Localização: <b>ESTRADA JURUAIA A MUZAMBINHO KM 04, Número SN ao SN</b><br>\n            Modalidade: <b>Reurb-E</b><br>\n            <br>\n           \n\n           \n         </div>\n        ','Despachado ao propietário',1,'2022-05-14 09:23:18','09:23:18',NULL,1),(9,'0011',NULL,'1','1','\n        <br>\n        <br>\n        \n    <div class=\"col-12\" style=text-align:center>\n     <img src=\"https://e-reurbsistema.com.br/sistema/assets/icones/325-Reurb-E.png\" class=\"\" width=\"200\"/><br>\n     <img src=\"https://e-reurbsistema.com.br/sistema/assets/icones/204-Reurb-S.png\" class=\"\" width=\"300\"/><br>\n    </div>\n    \n         <br><br>\n         <h1 style=text-align:center>DESPACHO</h1>\n         <br>\n\n         <div class=\"conteudo\">\n\n            \n            Procedimento nº: <b>0011</b><br>\n            Nome do núcleo urbano regularizado: <b>BAIRRO GOMES </b><br>\n            Localização: <b>ESTRADA JURUAIA A MUZAMBINHO KM 04, Número SN ao SN</b><br>\n            Modalidade: <b>Reurb-S</b><br>\n            <br>\n           \n\n           \n         </div>\n        ','',1,'2022-05-16 09:13:52','09:13:52',NULL,20),(10,'0011',NULL,'4','6','<p>&nbsp;</p>\r\n<div class=\"col-12\" style=\"text-align: center;\"><img class=\"\" src=\"../../assets/icones/325-Reurb-E.png\" width=\"200\" /><br /><img class=\"\" src=\"../../assets/icones/204-Reurb-S.png\" width=\"300\" /></div>\r\n<p><br /><br /></p>\r\n<h4 style=\"text-align: center;\">PROGRAMA DE REGULARIZA&Ccedil;&Atilde;O FUNDI&Aacute;RIA DE <br />INTERESSE SOCIAL DA PREFEITURA MUNICIPAL DE Juruaia &ndash; MG</h4>\r\n<p><br /><br /></p>\r\n<h4 style=\"text-align: center;\">PRF &ndash; PROJETO DE REGULARIZA&Ccedil;&Atilde;O FUNDI&Aacute;RIA &ndash; REURB &ndash; &ldquo;BAIRRO GOMES &rdquo;<br />PROCESSO ADMINISTRATIVO 0011</h4>\r\n<p><br /><br /></p>\r\n<div class=\"conteudo\" style=\"text-aling: justify;\">\r\n<p><strong>Equipe t&eacute;cnica e de apoio</strong></p>\r\n<br /><strong>. Taize Marcelino Martins Costa</strong> - Secret&aacute;ria Municipal de Promo&ccedil;&atilde;o Social<br /><strong>. Carlos Alberto de Souza Junior </strong> - Secret&aacute;rio Municipal de Obras, Meio Ambiente e Servi&ccedil;os Urbanos<br /><strong>. Luciana Salom&atilde;o Baroni </strong> - Arquiteta<br /><strong>. Maur&iacute;cio Macedo </strong> - Assessor Jur&iacute;dico<br /><strong>. Gustavo Pereira Andrade </strong> - Procurador Geral &ndash; Advogado OAB/MG 140.207<br /><strong>. Eloy Arraes Branco Avelino </strong> - Coordenador de Conv&ecirc;nios e Contratos<br /><strong>. Giseli Trindade Bueno </strong> - Controladoria Interna<br /><strong>. Edilberto Baqui&atilde;o da Silva </strong> - Engenheiro Civil &ndash; CREA-MG 64.575/D<br /><strong>. Celso Marques J&uacute;nior </strong> - Prefeito Municipal<br />\r\n<p><br /><br />Juruaia - MG 16 de Maio de 2022.</p>\r\n<p style=\"text-align: center;\">Celso Marques Junior<br />Prefeito Municipal</p>\r\n<br /><br />CAPA ...............................................................................................................................1<br />EQUIPE T&Eacute;CNICA E DE APOIO.............................................................................................................2<br />DADOS DO PROJETO.......................................................................................................................4<br />APRESENTA&Ccedil;&Atilde;O............................................................................................................................4<br />JURULARLEGAL............................................................................................................................ 10<br />DA A.R.T. DA OBRA/SERVI&Ccedil;O..........................................................................................................................10<br />ESTUDO PRELIMINAR DAS DESCONFORMIDADES E DA SITUA&Ccedil;&Atilde;O JUR&Iacute;DICA, URBAN&Iacute;STICA E AMBIENTAL DO N&Uacute;CLEO BARRA MANSA 01............................11<br />HIST&Oacute;RICO DA &Aacute;REA E CARACTERIZA&Ccedil;&Atilde;O DA POPULA&Ccedil;&Atilde;O...........................................................11<br />DAS CONDI&Ccedil;&Otilde;ES URBAN&Iacute;STICAS.................................................................................................................12<br />DO LAUDO DA DEFESA CIVIL........................................................................................................................15<br />DO LAUDO DO CODEMA Juruaia...............................................................................................................16<br />LEVANTAMENTO PLANIALTIM&Eacute;TRICO....................................................................................................17<br />DO VALOR ESTIMADO DO N&Uacute;CLEO.............................................................................................................21<br />DA PLANTA DO PER&Iacute;METRO DO N&Uacute;CLEO URBANO INFORMAL COM DEMONSTRA&Ccedil;&Atilde;O DAS MATR&Iacute;CULAS OU TRANSCRI&Ccedil;&Otilde;ES ATINGIDAS............................21<br />NOME DOS LOGRADOUROS...........................................................................................................................23<br />DO PER&Iacute;METRO URBANO...............................................................................................................................24<br />DO OF&Iacute;CIO AO MP...............................................................................................................................5<br />DO OF&Iacute;CIO AO CARTORIO DE IM&Oacute;VEIS....................................................................................................26<br />DOS MEMORIAIS DESCRITIVOS...................................................................................................................28<br />IDENTIFICA&Ccedil;&Atilde;O E CONCORD&Acirc;NCIA DE POSSE......................................................................................37<br />IDENTIFICA&Ccedil;&Atilde;O DA QUADRA A....................................................................................................................37<br />IDENTIFICA&Ccedil;&Atilde;O DA QUADRA B..................................................................................................................38<br />IDENTIFICA&Ccedil;&Atilde;O DA QUADRA C......................................................................................................................41<br />IDENTIFICA&Ccedil;&Atilde;O DA QUADRA D......................................................................................................................44<br />DA NOTIFICA&Ccedil;&Atilde;O DOS CONFRONTANTES.................................................................................................45<br />DO MEMORIAL DESCRITIVO DO SISTEMA VI&Aacute;RIO.................................................................................47<br />DA NOTIFICA&Ccedil;&Atilde;O DOS PROPRIET&Aacute;RIOS CONSTANTES NAS MATR&Iacute;CULAS..................................48<br />CERTID&Atilde;O DE CRONOGRAMA PREVISTO NO &sect;1&ordm; DO ART. 10 DA LEI COMPLEMENTAR MUNICIPAL 59/21...........................................................49<br />CONCLUS&Atilde;O................................................................................................................................<br />GLOSS&Aacute;RIO...............................................................................................................................52<br />REFER&Ecirc;NCIA..............................................................................................................................53<br />BIBLIOGRAFIA...........................................................................................................................54<br /><br /><br />\r\n<p>DADOS DO PROJETO</p>\r\n<p>PRF &ndash; Projeto de Regulariza&ccedil;&atilde;o Fundi&aacute;ria referente &agrave; parcial do n&uacute;cleo denominado &ldquo;BAIRRO GOMES &rdquo;, no Munic&iacute;pio de Juruaia &ndash; MG, pela modalidade de Interesse Social, conforme Portaria n&ordm; 552 de 26 de Agosto de 2021, Lei Complementar Municipal n&ordm; 59/2021, Decreto n&ordm; 1.355 de 31 de Maio de 2021 e a Lei Federal n&ordm; 13.465/2017.</p>\r\n<strong>PROPRIET&Aacute;RIO :</strong> Prefeitura de Juruaia <br /><strong>CNPJ :</strong> 18.368.668/0001-98 <br /><strong>Bairro :</strong> ESTRADA JURUAIA A MUZAMBINHO KM 04, N&uacute;mero SN ao SN<br /><strong>MUNIC&Iacute;PIO - UF :</strong> Juruaia<br /><strong>&Aacute;REA TOTAL (h&aacute;):</strong> 0000ha (0000m&sup2;)<br /><strong>PER&Iacute;METRO (m) :</strong> 00 metros<br /><br />\r\n<p>APRESENTA&Ccedil;&Atilde;O</p>\r\n<br />\r\n<p>O Projeto de Regulariza&ccedil;&atilde;o Fundi&aacute;ria &ndash; PRF tem como objetivo instruir e ao final promover a regulariza&ccedil;&atilde;o fundi&aacute;ria no bairro denominado &ldquo;BAIRRO GOMES &rdquo;.</p>\r\n<p>O n&uacute;cleo informal come&ccedil;ou a ser formado aproximadamente em meados do ano de 2012, iniciando a divis&atilde;o dos lotes e constru&ccedil;&atilde;o das edifica&ccedil;&otilde;es.</p>\r\n<p>&Eacute; formado predominantemente por popula&ccedil;&atilde;o de baixa renda, assim como o n&uacute;cleo que ainda &eacute; desprovido de infraestrutura, estando em falta liga&ccedil;&otilde;es de energia el&eacute;trica, rede de drenagem de &aacute;guas pluviais, pavimenta&ccedil;&atilde;o asf&aacute;ltica e cal&ccedil;adas, esgotamento sanit&aacute;rio existe parcialmente por meio de fo&ccedil;as s&eacute;pticas instaladas individualmente em algumas localidades do n&uacute;cleo.</p>\r\n<p>Segundo determina&ccedil;&atilde;o contida na Lei n&ordm; 13.465/2017, o Projeto de Regulariza&ccedil;&atilde;o Fundi&aacute;ria &eacute; documento obrigat&oacute;rio para a concess&atilde;o de legitima&ccedil;&atilde;o fundi&aacute;ria pelo Poder P&uacute;blico municipal. &Eacute; obriga&ccedil;&atilde;o tamb&eacute;m contida na Lei Complementar Municipal n&ordm; 59/2021.</p>\r\n<p>As normas preveem que o projeto de regulariza&ccedil;&atilde;o fundi&aacute;ria contemple, no m&iacute;nimo os itens a seguir:</p>\r\n<p style=\"margin-left: 15px;\">1. Levantamento planialtim&eacute;trico e cadastral, com georreferenciamento, subscrito por profissional competente, acompanhado de Anota&ccedil;&atilde;o de Responsabilidade T&eacute;cnica (ART) ou Registro de Responsabilidade T&eacute;cnica (RRT), que demonstrar&aacute; as unidades, as constru&ccedil;&otilde;es, o sistema vi&aacute;rio, as &aacute;reas p&uacute;blicas, os acidentes geogr&aacute;ficos e os demais elementos caracterizadores do n&uacute;cleo a ser regularizado;<br />2. Planta do per&iacute;metro do n&uacute;cleo urbano informal com demonstra&ccedil;&atilde;o das matr&iacute;culas ou transcri&ccedil;&otilde;es atingidas, quando for poss&iacute;vel;<br />3. Estudo preliminar das desconformidades e da situa&ccedil;&atilde;o jur&iacute;dica, urban&iacute;stica e ambiental;<br />4. Projeto urban&iacute;stico;<br />5. Memoriais descritivos; <br />6. Proposta de solu&ccedil;&otilde;es para quest&otilde;es ambientais, urban&iacute;sticas e de reassentamento dos ocupantes, quando for o caso; <br />7. Estudo t&eacute;cnico para situa&ccedil;&atilde;o de risco, quando for o caso; <br />8. Estudo t&eacute;cnico ambiental, para os fins previstos nesta Lei, quando for o caso; <br />9. Cronograma f&iacute;sico de servi&ccedil;os e implanta&ccedil;&atilde;o de obras de infraestrutura essencial, compensa&ccedil;&otilde;es urban&iacute;sticas, ambientais e outras, quando houver, definidas por ocasi&atilde;o da aprova&ccedil;&atilde;o do projeto de regulariza&ccedil;&atilde;o fundi&aacute;ria; <br />10. Termo de compromisso a ser assinado pelos respons&aacute;veis, p&uacute;blicos ou privados, pelo cumprimento do cronograma f&iacute;sico definido no inciso IX deste artigo.</p>\r\n<br />\r\n<p>Em atendimento &agrave; norma federal, portanto, o presente documento procurar&aacute; apresentar toda documenta&ccedil;&atilde;o e informa&ccedil;&otilde;es pertinentes &agrave;s previs&otilde;es legais. A apresenta&ccedil;&atilde;o obrigat&oacute;ria do Projeto de Regulariza&ccedil;&atilde;o Fundi&aacute;ria subsidiar&aacute; a Certid&atilde;o de Regulariza&ccedil;&atilde;o Fundi&aacute;ria, referente ao n&uacute;cleo informal, objeto do ato administrativo de Reurb-S, localizado no munic&iacute;pio de Juruaia.</p>\r\n<p><img src=\"../../assets/documentos/img/5b5d583b60e79d2d96124016aa9ebed0.jpg\" alt=\"\" width=\"572\" height=\"322\" /></p>\r\n<p>Para in&iacute;cio do processo administrativo, foi editado o Decreto n&ordm; 1.355-A em 31 de Maio de 2021, criando a Comiss&atilde;o de Regulariza&ccedil;&atilde;o Fundi&aacute;ria Urbana, sendo apta para instaurar e receber processos Administrativos necess&aacute;rios &agrave; regulariza&ccedil;&atilde;o fundi&aacute;ria, visando atender os requisitos da Lei Federal n&ordm; 13.465/17 e da Lei Complementar Municipal n&ordm; 59/2021:</p>\r\n</div>','Projeto de Regularização Fundiária',1,'2022-05-16 14:32:05','14:33:51','2022-05-16 14:33:51',20),(12,'0014',NULL,'1','1','<p><br /><br /></p>\r\n<div class=\"col-12\" style=\"text-align: center;\"><img class=\"\" src=\"../../assets/icones/325-Reurb-E.png\" width=\"200\" /><br /><img class=\"\" src=\"../../assets/icones/204-Reurb-S.png\" width=\"300\" /></div>\r\n<h1 style=\"text-align: center;\">CERTID&Atilde;O</h1>\r\n<div class=\"conteudo\">Procedimento n&ordm;: <strong>0014</strong><br />Nome do n&uacute;cleo urbano regularizado: <strong>Barra Mansa II</strong><br />Localiza&ccedil;&atilde;o: <strong>bairro barra mansa - Juruaia</strong><br />Modalidade: <strong>Reurb-S</strong><br /><br /></div>\r\n<div class=\"conteudo\">Certifico para os devidos fins que, por solicita&ccedil;&atilde;o da presidente desta Comiss&atilde;o, nesta data (25/05/2022) digitalizei os documentos f&iacute;sicos que j&aacute; haviam sido produzidos, para continuidade via procedimeneto eletr&ocirc;nico, conforme determinou o art. 17 da MP n&ordm; 1.085/21.</div>\r\n<div class=\"conteudo\">Os documentos est&atilde;o na aba \"anexar documentos\".&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Juruaia, 25 de maio de 2022.</div>\r\n<div class=\"conteudo\">Solicito ciente da Comiss&atilde;o da Reurb.</div>\r\n<h5 class=\"conteudo\">Gustavo Pereira Andrade</h5>\r\n<h5 class=\"conteudo\">membro da Comiss&atilde;o</h5>\r\n<h5 class=\"conteudo\">Procurador Geral do Munic&iacute;pio.</h5>\r\n<div class=\"conteudo\">&nbsp;</div>\r\n<div class=\"conteudo\">&nbsp;</div>','certidão de digitalização',1,'2022-05-25 15:55:45','19:37:33','2022-05-25 19:37:33',20),(13,'0014',NULL,'2','7','\n        <br>\n        <br>\n        \n    <div class=\"col-12\" style=text-align:center>\n     <img src=\"https://e-reurbsistema.com.br/sistema/assets/icones/325-Reurb-E.png\" class=\"\" width=\"200\"/><br>\n     <img src=\"https://e-reurbsistema.com.br/sistema/assets/icones/204-Reurb-S.png\" class=\"\" width=\"300\"/><br>\n    </div>\n    \n         <br><br>\n         <h1 style=text-align:center>TÍTULO</h1>\n         <br>\n\n         <div class=\"conteudo\">\n\n            \n            Procedimento nº: <b>0014</b><br>\n            Nome do núcleo urbano regularizado: <b></b><br>\n            Localização: <b>, Número  ao </b><br>\n            Modalidade: <b>Reurb-S</b><br>\n            <br>\n           \n\n           \n         </div>\n        ','teste',0,'2022-05-26 08:44:18','08:44:18',NULL,20),(14,'0014',NULL,'1','1','\n        <br>\n        <br>\n        \n    <div class=\"col-12\" style=text-align:center>\n     <img src=\"https://e-reurbsistema.com.br/sistema/assets/icones/325-Reurb-E.png\" class=\"\" width=\"200\"/><br>\n     <img src=\"https://e-reurbsistema.com.br/sistema/assets/icones/204-Reurb-S.png\" class=\"\" width=\"300\"/><br>\n    </div>\n    \n         <br><br>\n         <h1 style=text-align:center>DESPACHO</h1>\n         <br>\n\n         <div class=\"conteudo\">\n\n            \n            Procedimento nº: <b>0014</b><br>\n            Nome do núcleo urbano regularizado: <b></b><br>\n            Localização: <b>, Número  ao </b><br>\n            Modalidade: <b>Reurb-S</b><br>\n            <br>\n           \n\n           \n         </div>\n        ','certidão juntada de cronograma',0,'2022-07-01 07:54:36','07:54:36',NULL,20),(15,'0014',NULL,'1','1','<p><br><br></p>\r\n<div class=\"col-12\" style=\"text-align: center;\"><img class=\"\" src=\"../../assets/icones/325-Reurb-E.png\" width=\"200\"><br><img class=\"\" src=\"../../assets/icones/204-Reurb-S.png\" width=\"300\"></div>\r\n<p><br><br></p>\r\n<h1 style=\"text-align: center;\">DESPACHO</h1>\r\n<p>&nbsp;</p>\r\n<div class=\"conteudo\">Procedimento n&ordm;: <strong>0014</strong><br>Nome do n&uacute;cleo urbano regularizado: <strong>Barra Mansa 02</strong><br>Modalidade: <strong>Reurb-S</strong><br><br></div>\r\n<div class=\"conteudo\" style=\"text-align: justify;\">Por ordem da Presidente da Comiss&atilde;o, certifico que foi anexado, na data de hoje (01/07/2022), pelo Engenheiro Juliano RIbeiro Martins, o cronograma inicial de obra, bem como os laudos do CODEMA e DEFESA CIVIL acerca do n&uacute;cleo em regulariza&ccedil;&atilde;o. Solicito que a comiss&atilde;o acesse o documento na aba \"anexar documento\" para conhecimento, dando ci&ecirc;ncia nesta certid&atilde;o atrav&eacute;s de suas assinaturas.</div>\r\n<div class=\"conteudo\" style=\"text-align: justify;\">&nbsp;</div>\r\n<div class=\"conteudo\" style=\"text-align: justify;\">&nbsp;</div>\r\n<div class=\"conteudo\" style=\"text-align: right;\">Juruaia, 01 de Julho de 2022.</div>\r\n<div class=\"conteudo\" style=\"text-align: justify;\">&nbsp;</div>\r\n<div class=\"conteudo\" style=\"text-align: left;\">Vit&oacute;ria Beatriz Gon&ccedil;alves da Silva</div>\r\n<div class=\"conteudo\">&nbsp;</div>','Certidão de juntada de cronograma inicial',1,'2022-07-01 08:32:50','07:19:30','2022-07-04 07:19:30',25),(16,'0014',NULL,'2','7','<p><br><br></p>\r\n<div class=\"col-12\" style=\"text-align: center;\"><img class=\"\" src=\"../../assets/icones/325-Reurb-E.png\" width=\"200\"><br><img class=\"\" src=\"../../assets/icones/204-Reurb-S.png\" width=\"300\"></div>\r\n<p><br><br></p>\r\n<h1 style=\"text-align: center;\">MEMORANDO INTERNO</h1>\r\n<p>&nbsp;</p>\r\n<div class=\"conteudo\" style=\"text-align: left;\">Procedimento n&ordm;: <strong>0014</strong><br>Nome do n&uacute;cleo urbano regularizado: Barra Mansa 02<br>Modalidade: <strong>Reurb-S</strong></div>\r\n<div class=\"conteudo\" style=\"text-align: left;\">&nbsp;</div>\r\n<div class=\"conteudo\" style=\"text-align: left;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 14.0pt;\">EXCELENT&Iacute;SSIMO SENHOR PREFEITO</span></strong></div>\r\n<div class=\"conteudo\" style=\"text-align: left;\"><strong><span style=\"font-size: 14.0pt;\">Celso Marques Junior</span></strong></div>\r\n<div class=\"conteudo\" style=\"text-align: left;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 14.0pt;\">Ao gabinete<span style=\"mso-spacerun: yes;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></strong></div>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0.0001pt; line-height: normal; text-align: left;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 14.0pt;\">&nbsp;</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0.0001pt; line-height: normal; text-align: right;\" align=\"right\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 14.0pt;\"><span style=\"mso-spacerun: yes;\">&nbsp; </span></span></strong>Juruaia, 14 de julho de 2022</p>\r\n<p class=\"MsoNormal\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 14.0pt; line-height: 115%;\">&nbsp;</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 35.4pt; text-align: justify; text-indent: 35.4pt;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 14.0pt; line-height: 115%;\">&nbsp;</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 35.4pt; text-align: justify; text-indent: 35.4pt;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 14.0pt; line-height: 115%;\">&nbsp;</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 35.4pt; text-align: justify; text-indent: 35.4pt;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 14.0pt; line-height: 115%;\">&nbsp;</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 35.4pt; text-indent: 35.4pt; text-align: justify;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 14.0pt; line-height: 115%;\">Taize Marcelino Martins Costa, </span></strong><span style=\"font-size: 14.0pt; line-height: 115%;\">Presidente da Comiss&atilde;o de Regulariza&ccedil;&atilde;o Fundi&aacute;ria Urbana, nomeada pelo Decreto n&ordm; 1.355-A, de 31 de Maio de 2021, vem, com o devido respeito, na forma do Art. 2&ordm; do Decreto n&ordm; 1.355 de 31 de Maio de 2021, para, na forma da Lei Complementar Municipal n&ordm; 59 de 26 de Maio de 2021, da Lei Federal n&ordm; 13.465/17, e na forma do Art. 7&ordm; do Decreto 1.355/21, considerando a juntada do estudo preliminar, <strong style=\"mso-bidi-font-weight: normal;\"><u>REQUERER que seja editado decreto para declarar o n&uacute;cleo informal consolidado em regulariza&ccedil;&atilde;o pelo procedimento n&ordm; 552/2021 (n&uacute;mero eletr&ocirc;nico 0014), previamente denominado de Barra Mansa 02, como interesse social, tendo em vista o trabalho da Secretaria de Promo&ccedil;&atilde;o Social, in loco, que identificou mais de 90% dos possuidores de baixa renda, conforme a legisla&ccedil;&atilde;o vigente.</u></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 35.4pt; text-align: justify;\"><span style=\"font-size: 14.0pt; line-height: 115%;\">Com protestos da mais alta estima e considera&ccedil;&atilde;o.</span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\">&nbsp;</p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\">&nbsp;</p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: .0001pt; text-align: center; line-height: normal;\" align=\"center\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 14.0pt;\">Taize Marcelino Martins Costa</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: .0001pt; text-align: center; line-height: normal;\" align=\"center\">Presidente da Comiss&atilde;o de Regulariza&ccedil;&atilde;o Fundi&aacute;ria Urbana de Juruaia</p>\r\n<p>&nbsp;</p>','memorando para prefeito decretar núcleo social',1,'2022-07-14 12:43:21','13:58:16','2022-07-14 13:58:16',20),(17,'0014',NULL,'2','4','<p>&nbsp;</p>\r\n<div class=\"col-12\" style=\"text-align: center;\"><img class=\"\" src=\"../../assets/icones/325-Reurb-E.png\" width=\"200\"><br><img class=\"\" src=\"../../assets/icones/204-Reurb-S.png\" width=\"300\"></div>\r\n<p><br><br></p>\r\n<div class=\"conteudo\">\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0.0001pt; line-height: normal; text-align: justify;\"><span style=\"font-size: 12.0pt; font-family: \'Times New Roman\',\'serif\';\">Of&iacute;cio Geral n&ordm; 195/2022/CRF (Comiss&atilde;o de Regulariza&ccedil;&atilde;o Fundi&aacute;ria)</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0.0001pt; line-height: normal; text-align: justify;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 14.0pt;\">EXCELENT&Iacute;SSIMO(A) SENHOR(A) PROMOTOR (A) DA COMARCA DE MUZAMBINHO</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0.0001pt; line-height: normal; text-align: justify;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 14.0pt;\">&nbsp;</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0.0001pt; line-height: normal; text-align: justify;\" align=\"right\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 14.0pt;\"><span style=\"mso-spacerun: yes;\">&nbsp; </span></span></strong>Juruaia, 14 de julho de 2022</p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 14.0pt; line-height: 115%;\">&nbsp;</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 35.4pt; text-align: justify; text-indent: 35.4pt;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 14.0pt; line-height: 115%;\">&nbsp;</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 35.4pt; text-align: justify; text-indent: 35.4pt;\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 14.0pt; line-height: 115%;\">Taize Marcelino Martins Costa, </span></strong><span style=\"font-size: 14.0pt; line-height: 115%;\">Presidente da Comiss&atilde;o de Regulariza&ccedil;&atilde;o Fundi&aacute;ria Urbana, nomeada pelo Decreto n&ordm; 1.355-A, de 31 de Maio de 2021, vem, com o devido respeito, para, na forma da Lei Complementar Municipal n&ordm; 59 de 26 de Maio de 2021, da Lei Federal n&ordm; 13.465/17, e na forma do Art. 8&ordm; do Decreto 1.355/21, <strong style=\"mso-bidi-font-weight: normal;\"><u>INFORMAR este respeit&aacute;vel &oacute;rg&atilde;o, para os devidos fins</u></strong>, que o Munic&iacute;pio de Juruaia, atrav&eacute;s da Comiss&atilde;o de Regulariza&ccedil;&atilde;o Fundi&aacute;ria, iniciou de of&iacute;cio, atrav&eacute;s da Portaria n&ordm; 552 de 26 de Agosto de 2021, os procedimentos para regulariza&ccedil;&atilde;o fundi&aacute;ria do bairro com ocupa&ccedil;&atilde;o irregular chamado provisoriamente de &ldquo;Bairro Barra Mansa&rdquo;. Considerando a possibilidade legal de procedimentos parciais, demos continuidade no n&uacute;cleo indicado no estudo t&eacute;cnico preliminar conforme processo eletr&ocirc;nico, delimitado como &ldquo;barra mansa 02&rdquo;.</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 35.4pt; text-align: justify;\"><span style=\"font-size: 14.0pt; line-height: 115%;\"><span style=\"mso-tab-count: 1;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span>Colocamo-nos &agrave; disposi&ccedil;&atilde;o para eventuais esclarecimentos, e informamos que todo passo agora poder&aacute; ser acompanhado por este r. &oacute;rg&atilde;o ministerial no seguinte endere&ccedil;o eletr&ocirc;nico:<span style=\"mso-spacerun: yes;\">&nbsp; </span><a href=\"https://e-reurbjuruaia.com.br/\">https://e-reurbjuruaia.com.br/</a>, com o <strong style=\"mso-bidi-font-weight: normal;\"><u>c&oacute;digo do procedimento n&ordm; 0014</u></strong></span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 35.4pt; text-align: justify;\"><span style=\"font-size: 14.0pt; line-height: 115%;\">Para isso, V. S,. deve seguir a orienta&ccedil;&atilde;o neste of&iacute;cio para acesso.</span></p>\r\n<p class=\"MsoNormal\" style=\"margin-left: 35.4pt; text-align: justify;\"><span style=\"font-size: 14.0pt; line-height: 115%;\"><span style=\"mso-tab-count: 1;\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span>Com protestos da mais alta estima e considera&ccedil;&atilde;o.</span></p>\r\n<p class=\"MsoNormal\" style=\"text-align: justify;\">&nbsp;</p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0.0001pt; line-height: normal; text-align: justify;\" align=\"center\"><strong style=\"mso-bidi-font-weight: normal;\"><span style=\"font-size: 14.0pt;\">Taize Marcelino Martins Costa</span></strong></p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0.0001pt; line-height: normal; text-align: justify;\" align=\"center\">Presidente da Comiss&atilde;o de Regulariza&ccedil;&atilde;o Fundi&aacute;ria Urbana de Juruaia</p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0.0001pt; line-height: normal; text-align: justify;\" align=\"center\">&nbsp;</p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0.0001pt; line-height: normal; text-align: justify;\" align=\"center\">&nbsp;</p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0.0001pt; line-height: normal; text-align: justify;\" align=\"center\">&nbsp;</p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0.0001pt; line-height: normal; text-align: justify;\" align=\"center\">&nbsp;</p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0.0001pt; line-height: normal; text-align: justify;\" align=\"center\">&nbsp;</p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0.0001pt; line-height: normal; text-align: justify;\" align=\"center\">&nbsp;</p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0.0001pt; line-height: normal; text-align: justify;\" align=\"center\">&nbsp;</p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0.0001pt; line-height: normal; text-align: justify;\" align=\"center\">&nbsp;</p>\r\n<p class=\"MsoNormal\" style=\"margin-bottom: 0.0001pt; line-height: normal; text-align: justify;\" align=\"center\">&nbsp;</p>\r\n<p class=\"MsoNormal\" style=\"margin-bo