#
# Structure for table "notificacoes"
#

CREATE TABLE `notificacoes` (
  `id_notif` int(11) NOT NULL AUTO_INCREMENT,
  `id_notif_procedure` varchar(20) DEFAULT NULL,
  `id_notif_notificado` int(11) DEFAULT NULL,
  `notif_date` varchar(20) DEFAULT NULL,
  `notif_limite` varchar(20) DEFAULT NULL,
  `notif_entrega` varchar(20) DEFAULT NULL,
  `notif_situacao` varchar(50) DEFAULT NULL,
  `notif_tipo` varchar(20) DEFAULT NULL,
  `notif_conteudo` text,
  `notif_user` int(11) DEFAULT NULL,
  `notif_status` int(11) DEFAULT '1',
  `notif_post` varchar(20) DEFAULT NULL,
  PRIMARY KEY (`id_notif`)
) ENGINE=InnoDB AUTO_INCREMENT=25 DEFAULT CHARSET=utf8mb4;

#
# Data for table "notificacoes"
#

INSERT INTO `notificacoes` VALUES (3,'0011',1,'2022-05-16','2022-06-15','Expedida','Aguardando Entrega','Carta','\n        <br>\n        <div style=text-align:center>\n         <img src=\"https://e-reurbsistema.com.br/sistema/assets/icones/325-Reurb-E.png\" class=\"\" width=\"200\"/>\n        </div><br><br>\n         <h1 style=text-align:center>NOTIFICAÇÃO</h1>\n         <br>\n\n         <div class=\"conteudo\">\n\n            \n            Procedimento nº: <b>0011</b><br>\n            Nome do núcleo urbano regularizado: <b>BAIRRO GOMES </b><br>\n            Localização: <b>ESTRADA JURUAIA A MUZAMBINHO KM 04, Número SN ao SN</b><br>\n            Modalidade: <b>Reurb-S</b><br>\n            <br>\n            <p>\n                Sr(a). <b>Paulo Cesar Pereira Alves</b><br>\n                <b>,  ,  -  -  - CEP:</b>\n            </p>\n\n            <p>\n                Assunto: <b>: Notificação de procedimento de regularização fundiária ou demarcação urbanística</b>\n            </p><br>\n\n            <p>\n                Prezado(a). Senhor(a):\n            </p>\n            <br>\n            <p>\n                Através da presente, comunicamos Vossa Senhoria que tramita perante este município o\n                procedimento de regularização fundiária urbana/demarcação urbanística nº 0011 na\n                modalidade de Reurb-S núcleo urbano informal denominado BAIRRO GOMES  localizado no\n                ESTRADA JURUAIA A MUZAMBINHO KM 04, Número SN ao SN sendo atingidas as seguintes matrículas:\n                registradas perante o Cartorio de Registro de Imóveis de Muzambinho, com a descrição\n                georreferenciada em anexo.\n\n            </p>\n            <p>\n                Vossa Senhoria está sendo intimada na qualidade de Proprietário da aréa objeto\n                do procedimento de regularização fundiária ou demarcação urbanística nos termos dos art.\n                20 e 28 da Lei 13.465/17.\n            </p>\n            <p>\n                <b>NOTIFICO-O</b> para que se manifeste, caso queira, no prazo de 30 dias, sob pena da ausência\n                de impugnação implicar perda de eventual direito a titularização relativo ao imóvel objeto da\n                Reurb, nos termos do art. 20, §6º da Lei 13.465/17, ciente que a notificação não será\n                renovada no caso de titulação final a ser outorgada seja a de usucapião.\n            </p>\n            <p>\n                Os documentos referentes à demarcação urbanística (ou da regularização fundiária no rito\n                do art. 28 da Lei) estão à disposição para consultas na sede da Prefeitura Municipal,\n                localizada na Rua Ana Vitória - 37805-000, deste\n                Município, onde também receberá eventual impugnação ou anuência expressa.\n            </p><br>\n            <p>Juruaia,  16 de Maio de 2022</p>\n            <p>Atenciosamente</p><br>\n            <p style=text-align:center>Gustavo Pereira Andrade<br>Procurador Geral  - OAB/MG 140.207</p>\n            </div>\n            ',1,1,'2022-05-16 09:04:35'),(5,'0014',3,'2022-08-18','2022-09-17','Expedida','Anulada','Servidor','\n        <br>\n        <div style=text-align:center>\n         <img src=\"https://e-reurbsistema.com.br/sistema/assets/icones/325-Reurb-E.png\" class=\"\" width=\"200\"/>\n        </div><br><br>\n        <div>\n            <h1 class=\"text-center\">NOTIFICAÇÃO</h1>\n        </div>\n        <br>\n\n        <div class=\"conteudo\" style=text-align:justify>\n            Procedimento nº: <b>0014</b><br>\n            Nome do núcleo urbano regularizado: <b>Barra Mansa 02</b><br>\n            Localização: <b>, Número  ao </b><br>\n            Modalidade: <b>Reurb-S</b><br>\n            <br>\n            <p>\n                Sr(a). <b>Vicente Lopes</b><br>\n                <b>,  ,  - Juruaia - Minas Gerais - CEP:37805000</b>\n            </p>\n\n            <p>\n                Assunto: <b>: Notificação de procedimento de regularização fundiária ou demarcação urbanística</b>\n            </p><br>\n\n            <p>\n                Prezado(a). Senhor(a):\n            </p>\n            <br>\n            <p>\n                Através da presente, comunicamos Vossa Senhoria que tramita perante este município o\n                procedimento de regularização fundiária urbana/demarcação urbanística nº 0014 na\n                modalidade de Reurb-S núcleo urbano informal denominado Barra Mansa 02 localizado no\n                , Número  ao  sendo atingidas as seguintes matrículas:\n                registradas perante o Cartorio de Registro de Imóveis de Muzambinho, com a descrição\n                georreferenciada em anexo.\n\n            </p>\n            <p>\n                Vossa Senhoria está sendo intimada na qualidade de Proprietário da aréa objeto\n                do procedimento de regularização fundiária ou demarcação urbanística nos termos dos art.\n                20 e 28 da Lei 13.465/17.\n            </p>\n            <p>\n                <b>NOTIFICO-O</b> para que se manifeste, caso queira, no prazo de 30 dias, sob pena da ausência\n                de impugnação implicar perda de eventual direito a titularização relativo ao imóvel objeto da\n                Reurb, nos termos do art. 20, §6º da Lei 13.465/17, ciente que a notificação não será\n                renovada no caso de titulação final a ser outorgada seja a de usucapião.\n            </p>\n            <p>\n                Os documentos referentes à demarcação urbanística (ou da regularização fundiária no rito\n                do art. 28 da Lei) estão à disposição para consultas na sede da Prefeitura Municipal,\n                localizada na Rua Ana Vitória - 37805-000, deste\n                Município, onde também receberá eventual impugnação ou anuência expressa.\n            </p><br>\n            <p>Juruaia,  18 de Agosto de 2022</p>\n            <p>Atenciosamente</p><br>\n            <p style=text-align:center>Gustavo Pereira Andrade<br>Procurador Geral  - OAB/MG 140.207</p>\n        </div>\n        ',20,0,'2022-08-18 08:53:04'),(6,'0014',41,'2022-08-18','2022-09-17','Expedida','Anulada','Edital','\n        <br>\n        \n    <div class=\"col-12\" style=text-align:center>\n    <img src=\"https://e-reurbsistema.com.br/sistema/assets/icones/325-Reurb-E.png\" class=\"\" width=\"200\"/><br>\n    <img src=\"https://e-reurbsistema.com.br/sistema/assets/icones/204-Reurb-S.png\" class=\"\" width=\"300\"/><br>\n    </div>\n    <br><br>\n        <div>\n            <h1 style=text-align:center>EDITAL DE REGULARIZAÇÃO FUNDIÁRIA URBANA DE INTERESSE Reurb-S. PRAZO 30 (TRINTA) DIAS.</h1>\n        </div>\n        <br>\n\n        <div class=\"conteudo\" style=text-align:justify>\n\n            <p>\n                O Prefeito Municipal de Juruaia, no uso de suas atribuições legais, FAZ SABER aos terceiros eventualmente interessados e,\n                especialmente,PROPRIETÁRIOS CONSTANTES NA MATRÍCULA 15.975, que figura na qualidade de Proprietário posseiro matrícula/transcrição demarcada/atingida\n                pela regularização fundiária da matrícula da 15.975 núcleo urbano informal, tendo sido frustada a notificação pessoal\n                por Notificado por Edital.<br>\n\n                Damos ciência que está em trâmite neste Município um processo administrativo para fins de Regularização Fundiária de Reurb-S,\n                sob o nº 0014, com objetivo\n                de regularizar o núcleo urbano informal denominado Barra Mansa 02 localizado , Número  ao , com a descrição georreferenciada a seguir:<br>\n                 Inicia-se a descrição deste perímetro no ponto PT-01, de coordenadas N 7.648.276,20m e E 336.450,37m; deste segue confrontando com a propriedade de Rua Maria José de Almeida, com azimute de 104°53&#39;01,65&#34; por uma distância de 10,40m, até o ponto PT-02, de coordenadas N 7.648.273,53m e E 336.460,41m ; deste segue confrontando com Jurandir Alves Piza - Matricula Nº: 15.975, com a