#
# Structure for table "procedures"
#

CREATE TABLE `procedures` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `numero_procedimento` varchar(30) DEFAULT NULL,
  `cod_procedimento` varchar(255) DEFAULT NULL,
  `id_user` int(11) DEFAULT NULL,
  `municipio` int(11) DEFAULT NULL,
  `modalidade` varchar(20) DEFAULT NULL,
  `forma_organizacao` varchar(60) DEFAULT NULL,
  `tipo` varchar(20) DEFAULT NULL,
  `rito` varchar(255) DEFAULT NULL,
  `abertura_oficio` varchar(10) DEFAULT NULL,
  `status` int(2) DEFAULT '1',
  `data_cad` varchar(20) DEFAULT NULL,
  `procedure_situacao` varchar(30) DEFAULT NULL,
  `data_update` varchar(20) DEFAULT NULL,
  `nucleo_caracteristica` varchar(60) DEFAULT NULL,
  `nucleo_data_implantacao` varchar(20) DEFAULT NULL,
  `nucleo_nome` varchar(100) DEFAULT NULL,
  `nucleo_rural` varchar(10) DEFAULT NULL,
  `nucleo_d_rural` varchar(50) DEFAULT NULL,
  `nucleo_cdr` varchar(20) DEFAULT NULL,
  `nucleo_cep` varchar(20) DEFAULT NULL,
  `nucleo_endereco` varchar(80) DEFAULT NULL,
  `nucleo_numero_inical` varchar(15) DEFAULT NULL,
  `nucleo_numero_final` varchar(15) DEFAULT NULL,
  `nucleo_memorial` text,
  `nucleo_coordenadas` varchar(150) DEFAULT NULL,
  `nucleo_aprovacao_amb` varchar(80) DEFAULT NULL,
  `nucleo_equipamentos` varchar(255) DEFAULT NULL,
  `nucleo_natureza` varchar(100) DEFAULT NULL,
  `nucleo_natureza_caract` text,
  `nucleo_agua` varchar(30) DEFAULT NULL,
  `nucleo_energia` varchar(30) DEFAULT NULL,
  `nucleo_saneamento` varchar(30) DEFAULT NULL,
  `nucleo_drenagem` varchar(30) DEFAULT NULL,
  `nucleo_benfeitorias` varchar(40) DEFAULT NULL,
  `nucleo_cpf_res` varchar(20) DEFAULT NULL,
  `nucleo_nome_res` varchar(255) DEFAULT NULL,
  `nucleo_comp_urbanistica` varchar(30) DEFAULT NULL,
  `nucleo_comp_ambiental` varchar(20) DEFAULT NULL,
  `nucleo_notif` varchar(10) DEFAULT NULL,
  `nucleo_update_data` varchar(20) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=129 DEFAULT CHARSET=utf8mb4;

