CREATE TABLE `socioeconomico` (
  `id_socio` int(11) NOT NULL AUTO_INCREMENT,
  `id_socio_tab` varchar(100) DEFAULT NULL,
  `id_socio_procedure` varchar(20) DEFAULT NULL,
  `socio_cep` varchar(20) DEFAULT NULL,
  `socio_endereco` varchar(100) DEFAULT NULL,
  `socio_numero` varchar(20) DEFAULT NULL,
  `socio_complemento` varchar(30) DEFAULT NULL,
  `socio_bairro` varchar(30) DEFAULT NULL,
  `socio_cidade` varchar(50) DEFAULT NULL,
  `socio_estado` varchar(20) DEFAULT NULL,
  `socio_relacao_imovel` varchar(30) DEFAULT NULL,
  `socio_uso_imovel` varchar(30) DEFAULT NULL,
  `socio_adquiriu_lote` varchar(80) DEFAULT NULL,
  `socio_comprovam_posse` varchar(30) DEFAULT NULL,
  `socio_mais_domicio` varchar(10) DEFAULT NULL,
  `socio_tempo_ocupacao` varchar(40) DEFAULT NULL,
  `socio_atende_rede_anergia` varchar(10) DEFAULT NULL,
  `socio_atende_agua` varchar(10) DEFAULT NULL,
  `socio_atende_esgoto` varchar(10) DEFAULT NULL,
  `socio_atende_pavimento` varchar(10) DEFAULT NULL,
  `socio_captacao_agua` varchar(10) DEFAULT NULL,
  `socio_estrutura` varchar(15) DEFAULT NULL,
  `socio_reconstrucao` varchar(10) DEFAULT NULL,
  `socio_total_comodos` varchar(10) DEFAULT NULL,
  `socio_moradores_comodos` varchar(10) DEFAULT NULL,
  `socio_banheiros` varchar(10) DEFAULT NULL,
  `socio_paredes_internas` varchar(255) DEFAULT NULL,
  `socio_paredes_internas_condicoes` varchar(30) DEFAULT NULL,
  `socio_paredes_externas` varchar(255) DEFAULT NULL,
  `socio_paredes_externas_condicoes` varchar(30) DEFAULT NULL,
  `socio_cobertura` varchar(255) DEFAULT NULL,
  `socio_cobertura_condicoes` varchar(30) DEFAULT NULL,
  `socio_piso` varchar(100) DEFAULT NULL,
  `socio_piso_condicoes` varchar(30) DEFAULT NULL,
  `socio_eletricas` varchar(255) DEFAULT NULL,
  `socio_eletricas_cond` varchar(30) DEFAULT NULL,
  `socio_hidrossanitarias` varchar(255) DEFAULT NULL,
  `socio_hidrossanitarias_cond` varchar(30) DEFAULT NULL,
  `socio_sanitario` varchar(255) DEFAULT NULL,
  `socio_sanitario_cond` varchar(30) DEFAULT NULL,
  `socio_post` varchar(20) DEFAULT NULL,
  `socio_update` varchar(20) DEFAULT NULL,
  `socio_status` int(11) DEFAULT '1',
  PRIMARY KEY (`id_socio`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4;

